 89→const CodeBlock = ({
 90→	content,
 91→	language = '',
 92→	isError = false,
 93→}: {
 94→	content: string;
 95→	language?: string;
 96→	isError?: boolean;
 97→}) => {
 98→	const [isTruncated, setIsTruncated] = useState(content.length > 500);
 99→	const codeRef = useRef<HTMLElement>(null);
100→
101→	useEffect(() => {
102→		if (codeRef.current && (globalThis as any).hljs) {
103→			(globalThis as any).hljs.highlightElement(codeRef.current);
104→		}
105→	}, [content, isTruncated]);
106→
107→	return (
108→		<div style={{ position: 'relative', marginBottom: '1rem' }}>
109→			<pre
110→				style={{
111→					margin: 0,
112→					padding: '1rem',
113→					backgroundColor: isError ? '#fef2f2' : '#1e1e1e',
114→					color: isError ? '#991b1b' : '#d4d4d4',
115→					borderRadius: '6px',
116→					overflow: isTruncated ? 'hidden' : 'auto',
117→					fontSize: '0.875rem',
118→					fontFamily: 'monospace',
119→					border: isError ? '1px solid #fecaca' : 'none',
120→					maxHeight: isTruncated ? '300px' : 'none',
121→					position: 'relative',
122→					whiteSpace: 'pre-wrap',
123→					wordBreak: 'break-word',
124→				}}
125→			>
126→				<code ref={codeRef} className={language ? `language-${language}` : ''}>
127→					{content}
128→				</code>
129→				{isTruncated && content.length > 500 && (
130→					<div
131→						style={{
132→							position: 'absolute',
133→							bottom: 0,
134→							left: 0,
135→							right: 0,
136→							height: '60px',
137→							background: isError
138→								? 'linear-gradient(transparent, #fef2f2)'
139→								: 'linear-gradient(transparent, #1e1e1e)',
140→							pointerEvents: 'none',
141→						}}
142→					/>
143→				)}
144→			</pre>
145→			{content.length > 500 && (
146→				<button
147→					onClick={() => setIsTruncated(!isTruncated)}
148→					style={{
149→						marginTop: '0.5rem',
150→						padding: '0.5rem 1rem',
151→						backgroundColor: '#3b82f6',
152→						color: 'white',
153→						border: 'none',
154→						borderRadius: '4px',
155→						cursor: 'pointer',
156→						fontSize: '0.875rem',
157→					}}
158→				>
159→					{isTruncated ? 'Show more' : 'Show less'}
160→				</button>
161→			)}
162→		</div>
163→	);
164→};
