213→const FileDiff = ({
214→	filePath,
215→	oldString,
216→	newString,
217→}: {
218→	filePath: string;
219→	oldString: string;
220→	newString: string;
221→}) => {
222→	const diff = `--- a/${filePath}
223→+++ b/${filePath}
224→@@ -1,${oldString.split('\n').length} +1,${newString.split('\n').length} @@
225→${oldString
226→	.split('\n')
227→	.map((line) => '-' + line)
228→	.join('\n')}
229→${newString
230→	.split('\n')
231→	.map((line) => '+' + line)
232→	.join('\n')}`;
233→
234→	return (
235→		<>
236→			<ContentSection label="File Path">
237→				<code
238→					style={{
239→						background: '#f9f9f9',
240→						padding: '0.25rem 0.5rem',
241→						borderRadius: '4px',
242→						fontSize: '0.875rem',
243→						fontFamily: 'monospace',
244→					}}
245→				>
246→					{filePath}
247→				</code>
248→			</ContentSection>
249→			<ContentSection label="Diff">
250→				<CodeBlock content={diff} language="diff" />
251→			</ContentSection>
252→		</>
253→	);
254→};
