  5→import * as React from 'react';
  6→import { classNames as cx, type ClassNameArgument, type ComponentProps } from '../../../../util/componentUtil.ts';
  7→import type * as ReactTable from 'react-table';
  8→
  9→import { useScroller } from '../../../../layouts/util/Scroller.tsx';
 10→import { IconButton } from '../../../actions/IconButton/IconButton.tsx';
 11→import { TextLine } from '../../../text/TextLine/TextLine.tsx';
