 12→import { Dialog } from '../../containers/Dialog/Dialog.tsx';
 13→import { ModalProvider, type ModalProviderProps } from '../../util/overlays/modal/ModalProvider.tsx';
 14→
 15→import cl from './DialogModal.module.scss';
