14→export type LinkProps = React.PropsWithChildren<ComponentProps<'a'> & {
15→  /** Whether this component should be unstyled. */
16→  unstyled?: undefined | boolean,
17→  
18→  /* Size of the link */
19→  size?: 'small' | 'medium',
20→  
21→  /**
22→   * The label of the link. Additional UI elements may be added, e.g. a loading indicator. If full control over
23→   * the link content is desired, use `children` instead, this overrides the `label`.
24→   */
25→  label?: undefined | string,
26→  
27→  /**
