 12→import cl from './Tooltip.module.scss';
 13→
 14→
 15→export { cl as TooltipClassNames };
 16→
 17→export type TooltipSize = 'small' | 'medium' | 'large';
 18→
 19→export type TooltipArrowPosition = 'top' | 'right' | 'bottom' | 'left';
 20→
 21→export type TooltipProps = React.PropsWithChildren<ComponentProps<'div'> & {
 22→  /** Whether this component should be unstyled. */
 23→  unstyled?: undefined | boolean,
 24→  
 25→  /** Whether this tooltip should be rendered compact (minimal padding). */
 26→  compact?: undefined | boolean,
 27→  
 28→  /** Whether you want the component to have a fixed width. If unset, it will have dynamic size. */
 29→  size?: undefined | TooltipSize,
 30→  
 31→  /* If specified, will render an arrow at the given position. */
 32→  arrow?: undefined | TooltipArrowPosition,
 33→}>;
 34→/**
 35→ * A tooltip. Used by `TooltipProvider` to display a tooltip popover.
 36→ */
 37→export const Tooltip = (props: TooltipProps) => {
 38→  const {
 39→    children,
 40→    unstyled = false,
 41→    compact = false,
 42→    arrow,
 43→    size = undefined,
 44→    ...propsRest
 45→  } = props;
 46→  
 47→  const scrollerProps = useScroller();
 48→  
 49→  const arrowClassNames = ((): ClassNameArgument => {
 50→    if (!arrow) { return; }
 51→    
 52→    switch (arrow) {
 53→      case 'top': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-top']);
 54→      case 'right': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-right']);
 55→      case 'bottom': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-bottom']);
 56→      case 'left': return cx(cl['bk-tooltip--arrow'], cl['bk-tooltip--arrow-left']);
 57→      default: return assertUnreachable(arrow);
 58→    }
 59→  })();
 60→  
 61→  return (
 62→    <div
 63→      role="tooltip" // https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/tooltip_role
 64→      {...propsRest}
 65→      className={cx(
 66→        'bk',
 67→        { [cl['bk-tooltip']]: !unstyled, },
 68→        { [cl['bk-tooltip--compact']]: compact },
 69→        { [cl['bk-tooltip--small']]: size === 'small' },
 70→        { [cl['bk-tooltip--medium']]: size === 'medium' },
 71→        { [cl['bk-tooltip--large']]: size === 'large' },
 72→        arrowClassNames,
 73→        propsRest.className,
 74→      )}
 75→    >
 76→      <div {...scrollerProps} className={cx(cl['bk-tooltip__content'], 'bk-prose', scrollerProps.className)}>
 77→        {children}
 78→      </div>
 79→    </div>
 80→  );
 81→};
