347→type DataTableSyncProps<D extends object> = DataTableProps<D> & {
348→  classNameTable?: ClassNameArgument,
349→  placeholderEmpty?: React.ReactNode,
350→  placeholderSkeleton?: React.ReactNode,
351→  status: DataTableStatus,
352→};
353→export const DataTableSync = <D extends object>(props: DataTableSyncProps<D>) => {
354→  const {
355→    className,
356→    classNameTable,
357→    placeholderEmpty = <DataTablePlaceholderEmpty />,
358→    placeholderSkeleton = <DataTablePlaceholderSkeleton />,
359→    status,
360→    ...propsRest
361→  } = props;
362→  
363→  const isEmpty = status.ready && props.table.page.length === 0;
364→
365→  const renderPlaceholder = (): React.ReactNode => {
366→    if (!status.ready) {
367→      return placeholderSkeleton;
368→    }
369→    if (isEmpty) {
370→      return placeholderEmpty;
371→    }
372→    return undefined;
373→  };
374→  
375→  // Note: the wrapper div isn't really necessary, but we include it for structural consistency with `DataTableAsync`
376→  return (
377→    <div
378→      className={cx(cl['bk-data-table'], cl['bk-data-table--sync'], className )}
379→    >
380→      <DataTable
381→        {...propsRest}
382→        className={classNameTable}
383→        placeholder={renderPlaceholder()}
384→      />
385→    </div>
386→  );
387→};
388→DataTableSync.displayName = 'DataTableSync';
389→
390→
391→export type DataTableAsyncProps<D extends object> = DataTableProps<D> & {
392→  classNameTable?: ClassNameArgument,
393→  status: DataTableStatus,
394→  placeholderSkeleton?: React.ReactNode,
395→  placeholderEmpty?: React.ReactNode,
396→  placeholderError?: React.ReactNode,
397→  placeholderEndOfTable?: React.ReactNode,
398→  children?: React.ReactNode,
399→};
400→export const DataTableAsync = <D extends object>(props: DataTableAsyncProps<D>) => {
401→  const {
402→    className,
403→    classNameTable,
404→    status,
405→    placeholderSkeleton = <DataTablePlaceholderSkeleton />,
406→    placeholderEmpty = <DataTablePlaceholderEmpty />,
407→    placeholderError = <DataTablePlaceholderError />,
408→    placeholderEndOfTable,
409→    children,
410→    ...propsRest
411→  } = props;
412→  const table = props.table;
413→  
414→  const isFailed = status.error !== null;
415→  const isLoading = status.loading;
416→  const isEmpty = status.ready && table.page.length === 0;
417→  
418→  const renderPlaceholder = (): React.ReactNode => {
419→    if (isFailed) {
420→      return placeholderError;
421→    }
422→    if (isLoading) {
423→      // If there is still valid cached data, show it, otherwise show a skeleton placeholder
424→      return status.ready ? undefined : placeholderSkeleton;
425→    }
426→    if (isEmpty) {
427→      return placeholderEmpty;
428→    }
429→    return undefined;
430→  };
431→  
432→  return (
433→    <div
434→      className={cx(cl['bk-data-table'], cl['bk-data-table--async'], props.className )}
435→    >
436→      {children}
437→      
438→      <DataTable
439→        {...propsRest}
440→        className={props.classNameTable}
441→        placeholder={renderPlaceholder()}
442→        endOfTablePlaceholder={placeholderEndOfTable}
443→      />
444→    </div>
445→  );
446→};
